/**
 * SharedDocumentLink domain entity.
 *
 * Represents a shareable document link generated by a doctor for either:
 *   (a) a consultation  — consultationId is set, standaloneDocumentId is null
 *   (b) a standalone document (recipe/paraclinical/reposo outside a consultation)
 *                        — standaloneDocumentId is set, consultationId is null
 *
 * A DB-level XOR CHECK constraint enforces exactly one source is set.
 *
 * Business invariants enforced here:
 *   - canBeRevokedBy() enforces doctor ownership (anti-IDOR).
 *   - isActive() checks status.
 *   - atLeastOneSection() validates that sharing makes sense.
 */
export interface DocumentSections {
  report: boolean;
  prescriptions: boolean;
  ehr: boolean;
}

/**
 * New unified doc selection — stores which document types the doctor chose when
 * sharing, so the frontend can render the exact same component as the download.
 *
 * `types`            — document type keys chosen by the doctor.
 *                      Subset of: 'recipe' | 'paraclinical' | 'history' | 'rest' | 'informe'
 * `informeBlockKeys` — block keys selected within the 'informe' type (may be empty).
 * `restContent`      — text of the medical rest (reposo), frozen at share time.
 *                      The rest document is NOT persisted in blocksSnapshot (it lives only
 *                      in the frontend form state), so it must be snapshotted here when
 *                      the doctor chooses to share it.  Null when not provided or not shared.
 */
export interface DocSelection {
  types: string[];
  informeBlockKeys: string[];
  restContent?: string | null;
}

export interface SharedDocumentLinkCreateParams {
  id: string;
  /**
   * Null when the link is for a standalone document (standaloneDocumentId is set).
   * All pre-existing rows have this set — the XOR constraint prevents both being null
   * or both being non-null.
   */
  consultationId: string | null;
  doctorId: string;
  patientId: string;
  token: string;
  sections: DocumentSections;
  /**
   * New unified document selection (nullable).
   * When present, the frontend uses this for rendering; otherwise falls back to `sections`.
   */
  docSelection: DocSelection | null;
  status: 'active' | 'revoked';
  /** Accumulated failed verify-code attempts across ALL codes for this link. */
  failedAttempts: number;
  /** Timestamp of the last time a new code was requested for this link. */
  lastCodeRequestedAt: Date | null;
  createdAt: Date;
  /**
   * Set when the link is for a standalone document.
   * Null when the link is for a consultation.
   * Optional for backward-compatibility with existing call sites that omit it (defaults to null).
   */
  standaloneDocumentId?: string | null;
}

export class SharedDocumentLink {
  readonly id: string;
  readonly consultationId: string | null;
  readonly doctorId: string;
  readonly patientId: string;
  readonly token: string;
  readonly sections: DocumentSections;
  /**
   * New unified document selection (nullable).
   * When present, the frontend uses this for rendering; otherwise falls back to `sections`.
   */
  readonly docSelection: DocSelection | null;
  readonly status: 'active' | 'revoked';
  /** Accumulated failed verify-code attempts across ALL codes for this link. */
  readonly failedAttempts: number;
  /** Timestamp of the last time a new code was requested for this link. */
  readonly lastCodeRequestedAt: Date | null;
  readonly createdAt: Date;
  /**
   * Set when the link points to a standalone document.
   * Null when the link points to a consultation.
   */
  readonly standaloneDocumentId: string | null;

  /**
   * Maximum total failed attempts allowed across all codes for this link.
   * If the link reaches this threshold, verify-code is blocked even after
   * requesting a new code — the doctor must share a new link.
   */
  static readonly MAX_LINK_FAILED_ATTEMPTS = 10;

  /** Minimum seconds that must elapse between request-code calls. */
  static readonly CODE_REQUEST_COOLDOWN_SECONDS = 60;

  constructor(params: SharedDocumentLinkCreateParams) {
    this.id = params.id;
    this.consultationId = params.consultationId;
    this.doctorId = params.doctorId;
    this.patientId = params.patientId;
    this.token = params.token;
    this.sections = params.sections;
    this.docSelection = params.docSelection ?? null;
    this.status = params.status;
    this.failedAttempts = params.failedAttempts;
    this.lastCodeRequestedAt = params.lastCodeRequestedAt;
    this.createdAt = params.createdAt;
    this.standaloneDocumentId = params.standaloneDocumentId ?? null;
  }

  /** Returns true when the given doctor owns this link. Anti-IDOR guard. */
  canBeRevokedBy(doctorId: string): boolean {
    return this.doctorId === doctorId;
  }

  /** Returns true when the link is active (not revoked). */
  isActive(): boolean {
    return this.status === 'active';
  }

  /**
   * Returns true when at least one section is selected.
   * A link with no sections selected is meaningless.
   */
  atLeastOneSection(): boolean {
    return this.sections.report || this.sections.prescriptions || this.sections.ehr;
  }

  /**
   * Returns true when the link-level failed-attempt counter has been reached.
   * When true, verify-code is blocked regardless of which code is active.
   * Requesting a new code does NOT reset this counter.
   */
  isLinkBruteforceBlocked(): boolean {
    return this.failedAttempts >= SharedDocumentLink.MAX_LINK_FAILED_ATTEMPTS;
  }

  /**
   * Returns true when a new code was requested too recently.
   * Enforces a 60-second cooldown between request-code calls.
   */
  isCodeRequestOnCooldown(now: Date): boolean {
    if (!this.lastCodeRequestedAt) return false;
    const elapsedMs = now.getTime() - this.lastCodeRequestedAt.getTime();
    return elapsedMs < SharedDocumentLink.CODE_REQUEST_COOLDOWN_SECONDS * 1000;
  }

  static create(params: SharedDocumentLinkCreateParams): SharedDocumentLink {
    return new SharedDocumentLink(params);
  }

  /**
   * Factory method for standalone document links.
   * Sets standaloneDocumentId and leaves consultationId null.
   * The sections payload is a no-op placeholder (docSelection carries the real type).
   */
  static createForStandaloneDocument(params: {
    id: string;
    standaloneDocumentId: string;
    doctorId: string;
    patientId: string;
    token: string;
    docSelection: DocSelection;
    status: 'active' | 'revoked';
    failedAttempts: number;
    lastCodeRequestedAt: Date | null;
    createdAt: Date;
  }): SharedDocumentLink {
    return new SharedDocumentLink({
      id: params.id,
      consultationId: null,
      standaloneDocumentId: params.standaloneDocumentId,
      doctorId: params.doctorId,
      patientId: params.patientId,
      token: params.token,
      // sections is a legacy field; for standalone docs docSelection carries the type.
      sections: { report: false, prescriptions: false, ehr: false },
      docSelection: params.docSelection,
      status: params.status,
      failedAttempts: params.failedAttempts,
      lastCodeRequestedAt: params.lastCodeRequestedAt,
      createdAt: params.createdAt,
    });
  }
}
